	@Test
	void timeoutKeepsPrecedenceWhenSourceOperationAndCloseFail() throws Exception {
		for (Operation operation : Operation.values()) {
			CloseOnlyIteration source = new CloseOnlyIteration(operation);
			source.operationFailure = new IllegalStateException("source operation failed during cancellation");
			source.closeFailure = new IllegalStateException("source close failed");
			try (QueryExecutionDeadline deadline = QueryExecutionDeadline.start(60_000);
					ExecutorService executor = Executors.newSingleThreadExecutor()) {
				DeadlineIteration timed = new DeadlineIteration(source, deadline);
				try {
					Future<?> call = executor.submit(() -> operation.invoke(timed));
					assertTrue(source.entered.await(5, TimeUnit.SECONDS));
					timed.interrupt();
					ExecutionException failure = assertThrows(ExecutionException.class,
							() -> call.get(5, TimeUnit.SECONDS));
					assertSame(timed.timeout, failure.getCause());
					assertEquals(1, timed.timeout.getSuppressed().length);
					assertSame(source.operationFailure, timed.timeout.getSuppressed()[0]);
					assertSame(source.closeFailure, assertThrows(IllegalStateException.class, timed::close));
					assertEquals(1, source.closeCalls.get(), "a failing close must still be claimed exactly once");
				} finally {
					source.released.countDown();
					timed.close();
				}
			}
		}
	}

