	@Test
	void automaticCloseRetainsDelegateCallDeadline() {
		for (Operation operation : Operation.values()) {
			CloseOnlyIteration source = new CloseOnlyIteration(operation);
			source.released.countDown();
			source.available = false;
			if (operation == Operation.NEXT) {
				source.operationFailure = new NoSuchElementException("source exhausted");
			} else if (operation == Operation.REMOVE) {
				source.operationFailure = new IllegalStateException("source cannot remove");
			}
			try (QueryExecutionDeadline deadline = QueryExecutionDeadline.start(60_000);
					DeadlineIteration timed = new DeadlineIteration(source, deadline)) {
				if (source.operationFailure == null) {
					assertFalse(timed.hasNext());
				} else {
					assertSame(source.operationFailure,
							assertThrows(RuntimeException.class, () -> operation.invoke(timed)));
				}
				assertSame(deadline, timed.closeDeadline,
						"automatic close requests must retain the deadline of the delegate call");
				if (operation == Operation.HAS_NEXT) {
					assertSame(deadline, source.closeDeadline,
							"exhaustion source close must retain the deadline after the delegate call exits");
				}
				assertEquals(1, source.closeCalls.get());
			}
		}
	}

